<?php require_once 'includes/components.php'; if(($_SESSION['auth_user']['role']??'')!=='admin'){header('Location:auth.php');exit;} ?><!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Thư viện ảnh | NALI</title><link rel="stylesheet" href="common.css"><link rel="stylesheet" href="content-pages.css"></head><body><?php renderHeader();?><main class="content-wrap"><h1>Tải ảnh lên</h1><p>Ảnh JPG/PNG/WebP tối đa 5 MB sẽ được tự co tối đa 1920px và nén WebP. Sao chép đường dẫn để dán vào quản trị nội dung.</p><input id="image" type="file" accept="image/jpeg,image/png,image/webp"><button class="content-button" id="upload">Tải ảnh</button><p id="result"></p><img id="preview" alt="Xem trước ảnh vừa tải" style="display:none;max-width:420px;border-radius:12px"></main><?php renderFooter();?><script>upload.onclick=async()=>{if(!image.files[0])return;let f=new FormData();f.append('image',image.files[0]);let r=await fetch('upload_image.php',{method:'POST',body:f}),d=await r.json();result.textContent=d.success?d.path:d.message;if(d.success){preview.src=d.path;preview.style.display='block';navigator.clipboard?.writeText(d.path)}}</script></body></html>
